/// 可中断休眠：每秒检查一次停止标志
async fn sleep_cancellable(rt: &IlinkRuntime, secs: u64) {
    for _ in 0..secs {
        if rt.stop.load(Ordering::Relaxed) {
            return;
        }
        tokio::time::sleep(Duration::from_secs(1)).await;
    }
}

