        self: Pin<&mut Self>,
        cx: &mut Context<'_>,
        buf: &mut tokio::io::ReadBuf<'_>,
    ) -> Poll<io::Result<()>> {
        match self.get_mut() {
            AgentStream::Unix(s) => Pin::new(s).poll_read(cx, buf),
            #[cfg(windows)]
            AgentStream::Pipe(p) => Pin::new(p).poll_read(cx, buf),
        }
    }
}

